import type { LangVocabChapter } from '../../lib/langTypes'

/**
 * HSK 3 (HSK 2.0 syllabus): the 300 new words introduced at level 3
 * (HSK 1 and HSK 2 words are not repeated), grouped by theme.
 * Word ids run h3-1 … h3-300 in the order they appear below.
 */

/** [word, reading, pos, meaningTh, mnemonicTh, example, exampleReading, exampleTh] */
type Raw = [string, string, string, string, string, string, string, string]

let counter = 0

function chapter(
  id: string,
  emoji: string,
  titleTh: string,
  description: string,
  raw: Raw[],
): LangVocabChapter {
  return {
    id,
    emoji,
    titleTh,
    description,
    words: raw.map(([word, reading, pos, meaningTh, mnemonicTh, example, exampleReading, exampleTh]) => ({
      id: `h3-${++counter}`,
      word,
      reading,
      pos,
      meaningTh,
      mnemonicTh,
      example,
      exampleReading,
      exampleTh,
    })),
  }
}

